# ================= BATCH 16: sixteen new situations (docs/research/words-real-exchanges-3.md) =================
# Every reply leaves a hook; some carry a reason, a limit or a cost (25 to 70 words); openings are small and specific.
KEY.update({"funeral-cause":"loss","layoff-terms":"loss","eviction-terms":"loss","scandal-comment":"threat","recall-confront":"threat",
 "hearing-testify":"routine","law-reaches":"news-received","conflict-accuse":"threat","betrayal-explain":"threat","ally-return":"routine",
 "owed-apology":"routine","appointment-offer":"honor","floor-switch":"vote-wanted","protest-warning":"threat","neighbor-argument":"threat","favor-job":"favor-asked"})
F='funeral-cause'
L(N,N,R,F,[("The service is over. People are standing around the coffee urn, and {name} makes their way over to you.","solemn")])
L('open','greet',A,F,[("{deceased} talked about you, you know.","solemn")])
L('state','request',A,F,[("{deceased} had one more fight left at the council and never got to it. Somebody has to finish it. I'd like it to be you.","solemn")])
L('reply','promise',Y,F,[("Tell me what it was, and I'll put it on the agenda myself. I can't promise it passes. I can promise it gets a vote with {deceased}'s name on it.","tender")])
L('reply','decline',Y,F,[("Not today. Let me get through today. Call my office Monday, and we'll talk about it properly.","tender")])
L('reply','ask',Y,F,[("What was it, exactly?","tender")])
L('reply','deflect',Y,F,[("This isn't the place for it.","guarded")])
L('follow','answer',A,F,[("Every spring {deceased} called the council about the same thing, and every spring somebody said next year.","solemn")],after="What was it, exactly?")
L('reply','promise',Y,F,[("Then it goes on the agenda this spring. I'll call you when it's scheduled.","tender")],after='answer')
L('reply','decline',Y,F,[("That's the state's road. I can carry it to them. I can't make them say yes.","guarded")],after='answer')
L('follow','thank',A,F,[("That's all I wanted. Thank you.","solemn"),("{deceased} would have liked that.","solemn")])
L('follow','accept',A,F,[("Monday, then.","solemn")],after='decline')
L('follow','accept',A,F,[("You're right. I'm sorry.","solemn")],after='deflect')
L('follow','press',A,F,[("If not here, when? Nobody returns my calls.","hurt")])
L('reply','leave',Y,F,[("I need some air.","solemn")])
L('close','accept',A,F,[("Go on. I'll find you later.","solemn")],after='leave',outcome='open')
F='layoff-terms'
L(N,N,R,F,[("{name} asks you into the small office and shuts the door. There's an envelope on the desk with your name on it.","braced")])
L('open','greet',A,F,[("Sit down a minute.","nervous")])
L('state','deliver-news',A,F,[("They're cutting the second shift. Your job's one of them. Friday's your last day.","solemn")])
L('reply','ask',Y,F,[("Why me? I've got more years than half that shift.","hurt")])
L('reply','bargain',Y,F,[("Two more months of pay and you'll write me a reference. Then I go quietly.","braced")])
L('reply','confront',Y,F,[("You knew this last week. You let me pick up Saturday.","braced")])
L('reply','accept',Y,F,[("Okay. What do I sign?","calm")])
L('follow','answer',A,F,[("It wasn't my list. They went by department, not years. I argued for you. I lost.","solemn")],after='ask')
L('follow','accept',A,F,[("Two months I can't do. Six weeks I can. And the reference you'll have either way.","calm")],after='bargain')
L('follow','refuse',A,F,[("I don't have that kind of money to give out. I'm sorry.","guarded")],after='bargain')
L('follow','apologize',A,F,[("You're right. I should have told you. I wasn't allowed to.","contrite")],after='confront')
L('follow','deflect',A,F,[("That's not how it went.","guarded")],after='confront')
L('follow','promise',A,F,[("Sign at the bottom. And I'll write the reference myself, tonight.","calm")],after='accept')
L('reply','bargain',Y,F,[("Then give me two months' pay and a reference, in writing.","calm")],after='answer')
L('reply','confront',Y,F,[("You argued for me. Sure.","braced")],after='answer')
L('reply','accept',Y,F,[("Fine. Six weeks. Put it in the letter.","calm")],after='accept')
L('reply','thank',Y,F,[("Thanks. I mean it.","calm")],after='promise')
L('reply','leave',Y,F,[("I'm going to clean out my locker.","hurt")])
L('close','accept',A,F,[("Take your time with it.","solemn")],after='leave',outcome='open')
F='eviction-terms'
L(N,N,R,F,[("{name} is on your front step with a folded paper and doesn't come in.","braced")])
L('open','greet',A,F,[("Got a minute? It's about the rent.","nervous")])
L('state','deliver-news',A,F,[("This is a notice. You've got thirty days. I'm sorry it came to this.","guarded")])
L('reply','plea',Y,F,[("I can pay half now and the rest on the first. My hours got cut. They're coming back.","anxious")])
L('reply','ask',Y,F,[("Is there a hearing date on that?","anxious")])
L('reply','confront',Y,F,[("You can't just put me out. I know my rights.","braced")])
L('reply','accept',Y,F,[("Okay. Thirty days.","hurt")])
L('follow','accept',A,F,[("Half now and the rest on the first. In writing. Miss it and we're back here.","guarded")],after='plea')
L('follow','refuse',A,F,[("I've heard the first before. Three times.","guarded")],after='plea')
L('follow','answer',A,F,[("It's on the back. The court sends its own letter.","calm")],after='ask')
L('follow','threaten',A,F,[("Then I'll see you in court.","braced")],after='confront')
L('follow','deflect',A,F,[("Talk to the management company. I just deliver these.","guarded")],after='confront')
L('follow','promise',A,F,[("I'll give the deposit back clean if the place is clean.","calm")],after='accept')
L('reply','plea',Y,F,[("Give me till the hearing. If I can't pay by then, I'll go.","anxious")],after='answer')
L('reply','plea',Y,F,[("Then I'll get it to you Friday. All of it I can find.","anxious")],after='refuse')
L('reply','accept',Y,F,[("Fine. Court, then.","braced")],after='threaten')
L('reply','thank',Y,F,[("It'll be clean.","calm")],after='promise')
L('reply','leave',Y,F,[("I have to go inside.","hurt")])
L('close','warn',A,F,[("Thirty days.","guarded")],after='leave',outcome='open')
F='scandal-comment'
L(N,N,R,F,[("Your phone rings at four. It's {name} from {outlet}.","braced")])
L('open','greet',A,F,[("I'm filing at five, so I'll be quick.","calm")])
L('state','ask',A,F,[("We're running a story about {story}. I want to give you a chance to respond.","calm",["story"]),("We're running a story about you tomorrow. I want to give you a chance to respond.","calm")])
L('reply','confess',Y,F,[("It's true, and I should have said so sooner. Put that in. And put in that I'm fixing it.","contrite")])
L('reply','deny',Y,F,[("That's wrong. What's the specific claim, and who's your source on the date?","braced")])
L('reply','refuse',Y,F,[("No comment at this time.","guarded")])
L('reply','confront',Y,F,[("Who gave you this?","braced")])
L('reply','lie',Y,F,[("I was never there. Check the minutes.","calm")])
L('follow','ask',A,F,[("Fixing it how?","curious")],after='confess')
