L('follow','accept',A,F,[("Then I'll say you declined to comment.","calm")],after='refuse')
L('follow','answer',A,F,[("You know I can't tell you that.","calm")],after='confront')
L('follow','confront',A,F,[("The minutes have you there.","calm",K)],after='lie')
L('follow','thank',A,F,[("Then I'll put that you deny it.","calm")],after='lie')
L('reply','answer',Y,F,[("I'm paying it back, and I've asked the clerk to post the records. You can have them tomorrow.","calm")],after='Fixing it how?')
L('reply','deny',Y,F,[("One thing: the date's wrong. I can send you the calendar.","calm")],after='press')
L('reply','confess',Y,F,[("Fine. Most of it's right. Give me until four-thirty for a statement.","guarded")],after='press')
L('reply','refuse',Y,F,[("Then talk to my lawyer.","braced")],after='press')
L('follow','accept',A,F,[("Send it. If it checks out, I'll change it.","calm")],after="One thing: the date's wrong. I can send you the calendar.")
L('follow','thank',A,F,[("Four-thirty. I'll hold the space.","calm")],after="Fine. Most of it's right. Give me until four-thirty for a statement.")
L('follow','thank',A,F,[("That goes in too.","calm")],after="I'm paying it back, and I've asked the clerk to post the records. You can have them tomorrow.")
L('reply','leave',Y,F,[("I have to go.","braced")])
L('close','accept',A,F,[("It runs at six.","calm")],after='leave',outcome='open')
F='recall-confront'
L(N,N,R,F,[("{name} is at a folding table outside the grocery store with a clipboard and a stack of petitions. You'd have to walk right past.","braced")])
L('open','greet',A,F,[("You got a minute? I'm not here to yell.","calm")])
L('state','confront',A,F,[("We're collecting signatures to recall you. You voted for {bill}, and people here are paying for it.","braced")])
L('reply','ask',Y,F,[("Is that the only reason on the petition?","calm")])
L('reply','confront',Y,F,[("You're telling people I did things I didn't do.","braced")])
L('reply','boast',Y,F,[("Go ahead. I'll win the vote.","proud")])
L('reply','deflect',Y,F,[("It's your right. Good luck with it.","guarded")])
L('follow','answer',A,F,[("That and you stopped holding office hours.","braced")],after='ask')
L('follow','confront',A,F,[("Then say that at the forum. In front of people.","braced")])
L('follow','press',A,F,[("Don't walk past. Tell me why you voted for it.","braced")],after='deflect')
L('reply','offer',Y,F,[("I voted for it because the other choice was a cut that hurt more people. Put me on the forum. I'll say that and take questions until they run out.","calm")])
L('reply','offer',Y,F,[("Fair. Office hours start again next week, and you can come first.","calm")],after="That and you stopped holding office hours.")
L('reply','confront',Y,F,[("I'm not debating you at a card table.","braced")],after='press')
L('follow','thank',A,F,[("Then we'll set it up. I'll hold you to it.","calm")],after='offer')
