L('close','warn',A,F,[("We'll have the signatures by Friday.","braced")],after='leave',outcome='open')
F='hearing-testify'
L(N,N,R,F,[("It's public comment on {bill}. {name} calls your name, and you step up to the microphone.","braced")])
L('open','call-to-order',A,F,[("You have three minutes.","calm")])
L('state','call-to-order',A,F,[("Please state your name and address for the record.","calm")])
L('reply','tell',Y,F,[("I've read {bill} twice. The part that worries me is who it reaches first, and nobody on my street was asked. I'd like the council to hear from them before it votes.","braced")])
L('reply','request',Y,F,[("Hold the vote one week, and hear from the people it reaches first.","calm")])
L('reply','confront',Y,F,[("You decided this before tonight. This is for show.","braced")])
L('reply','ask',Y,F,[("Has anybody up there talked to the people this reaches?","braced")])
L('follow','ask',A,F,[("Is your concern the bill, or how it was done?","calm")],after='tell')
L('follow','thank',A,F,[("Thank you. It's in the record.","calm")])
