L('follow','refuse',A,F,[("We can't respond to that during public comment.","guarded")])
L('follow','warn',A,F,[("Please address the chair, not the members.","guarded")],after='confront')
L('follow','answer',A,F,[("Staff, can you answer that?","calm")],after='ask')
L('reply','answer',Y,F,[("How it was done. Ask us first, and I'll sit down.","calm")],after="Is your concern the bill, or how it was done?")
L('reply','request',Y,F,[("Then I'd like that in writing, please.","calm")],after='answer')
L('reply','apologize',Y,F,[("I'm sorry. I'll address the chair.","guarded")],after='warn')
L('reply','thank',Y,F,[("Thank you.","calm")])
L('reply','leave',Y,F,[("I'm done.","braced")])
L('close','accept',A,F,[("Next speaker.","calm")],after='leave',outcome='open')
F='law-reaches'
L(N,N,R,F,[("You're in line at the pharmacy when {name} turns around.","braced")])
L('open','greet',A,F,[("You voted for it.","braced")])
L('state','tell',A,F,[("{bill} took effect this month. It's costing my family real money, and I'd like to hear you explain it.","braced")])
L('reply','tell',Y,F,[("I did vote for it. It was trading against a cut that would have hit more families than this one. That's not an answer for yours, I know.","calm")])
L('reply','promise',Y,F,[("Tell me how much. If there's a hardship waiver, I'll find it, and I'll call you myself.","calm")])
L('reply','deflect',Y,F,[("This isn't the place.","guarded")])
L('reply','blame',Y,F,[("The state forced our hand on that.","guarded")])
L('follow','disagree',A,F,[("That's not an answer for my kids.","hurt")])
L('follow','accept',A,F,[("At least you said it to my face.","calm")])
L('follow','thank',A,F,[("Every month. I'll hold you to it.","calm")],after='promise')
L('follow','press',A,F,[("Then where is? You don't answer email.","braced")],after='deflect')
L('reply','tell',Y,F,[("No, it isn't. Let me see if there's a waiver. Here's my card.","contrite")],after='disagree')
L('reply','promise',Y,F,[("Give me your number. I'll call before Friday.","calm")])
L('reply','leave',Y,F,[("I'm sorry. I have to go.","guarded")])
L('close','warn',A,F,[("I'll remember this in November.","braced")],after='leave',outcome='open')
F='conflict-accuse'
L(N,N,R,F,[("Before the vote on {bill}, {name} leans over and lowers their voice.","braced")])
L('open','greet',A,F,[("Can I ask you something before we vote?","calm")])
L('state','confront',A,F,[("Is there a firm on the bid list for {bill} that you have money in?","braced")])
L('reply','tell',Y,F,[("There is. I reported it in writing, and counsel said I could vote. I'll get you the letter.","calm")])
L('reply','deny',Y,F,[("No. Where did you hear that?","braced")])
L('reply','confront',Y,F,[("Say that on the record if you believe it.","braced")])
L('reply','offer',Y,F,[("I'll step out on this one. Not because I've done anything, but because you asked, and others will.","calm")])
L('reply','lie',Y,F,[("Never heard of the firm.","calm")])
L('follow','ask',A,F,[("Then why vote at all?","braced")],after='tell')
L('follow','accept',A,F,[("Send me the letter. That's all I need.","calm")])
L('follow','press',A,F,[("It's on the list in the packet. Page four.","braced")],after='deny')
L('follow','confront',A,F,[("I will.","braced")],after='confront')
L('follow','confront',A,F,[("It's on page four of the packet.","braced",K)],after='lie')
L('reply','tell',Y,F,[("Because the rule says I can, and the people who sent me sent me to vote.","braced")],after='ask')
L('reply','offer',Y,F,[("Fine. I'll step out.","guarded")])
L('reply','leave',Y,F,[("We're voting.","braced")])
L('close','warn',A,F,[("Then I'll raise it from the floor.","braced")],after='leave',outcome='open')
F='betrayal-explain'
L(N,N,R,F,[("{name} is waiting by your car. They don't say hello.","hurt")])
L('open','greet',A,F,[("You didn't call me back.","hurt")])
L('state','confess',A,F,[("I'm the one who gave the paper your memo. You should hear it from me.","contrite")])
L('reply','ask',Y,F,[("Why?","hurt")])
L('reply','confront',Y,F,[("All these years, and you hand my memo to a reporter.","hurt")])
L('reply','comfort',Y,F,[("Okay. Thank you for telling me yourself.","tender")])
L('reply','leave',Y,F,[("I can't do this right now.","hurt")])
L('follow','answer',A,F,[("Because you were going to bury it, and people on my street were going to pay for it. I didn't see another way.","braced")],after='ask')
L('follow','apologize',A,F,[("I know. I'd do it again, and I'm sorry.","contrite")],after='confront')
L('follow','deflect',A,F,[("You'd have done the same.","guarded")],after='confront')
L('follow','thank',A,F,[("I didn't think you'd say that.","tender")],after='comfort')
L('reply','bargain',Y,F,[("Then you owe me one. A big one.","guarded")])
L('reply','comfort',Y,F,[("You might be right. I'm still angry.","hurt")],after='answer')
L('close','warn',A,F,[("I'll go.","hurt")],after='leave',outcome='open')
F='ally-return'
L(N,N,R,F,[("{name} stops you on the courthouse steps. You haven't spoken since the split.","guarded")])
L('open','greet',A,F,[("I saw your numbers.","guarded")])
L('state','request',A,F,[("I was wrong to walk out on you, and I said so to my people last night. I want back in.","contrite")])
L('reply','agree',Y,F,[("Then come by Thursday. Bring your people.","calm")])
L('reply','bargain',Y,F,[("Say it at Tuesday's meeting, in front of everyone. Then we'll talk.","guarded")])
L('reply','refuse',Y,F,[("You were loud about it. You can be loud somewhere else.","braced")])
L('reply','ask',Y,F,[("What changed?","guarded")])
L('follow','answer',A,F,[("I found out who was paying for the other side. I didn't like it.","guarded")],after='ask')
L('follow','accept',A,F,[("Tuesday. I'll say it.","calm")],after='bargain')
L('follow','bargain',A,F,[("I'll say it Tuesday if you'll back my district on the budget.","calm")],after='bargain')
L('follow','plea',A,F,[("I'm asking. I don't ask much.","contrite")],after='refuse')
L('follow','accept',A,F,[("Fair enough.","guarded")],after='refuse')
L('follow','thank',A,F,[("Thursday.","calm")],after='agree')
L('close','accept',A,F,[("I'll see you around.","guarded")],after='leave',outcome='open')
F='owed-apology'
L(N,N,R,F,[("After the meeting, {name} waits until the room is nearly empty.","hurt")])
L('open','greet',A,F,[("Do you have a minute, or are you going to walk past me again?","hurt")])
L('state','confront',A,F,[("You made a fool of me in front of the whole council, and you never said a word after.","hurt")])
L('reply','apologize',Y,F,[("You're right. I went after you to win a point, and it wasn't fair. I'll say so at the next meeting.","contrite")])
L('reply','tell',Y,F,[("I went after the idea, not you. I can see it didn't come across that way.","calm")])
L('reply','deflect',Y,F,[("It was a tense night for everybody.","guarded")])
L('reply','confront',Y,F,[("You started it.","braced")])
L('follow','accept',A,F,[("At the next meeting. Okay.","calm"),("All right. That I'll take.","calm")])
L('follow','press',A,F,[("A tense night. That's what you've got?","hurt")],after='deflect')
L('follow','press',A,F,[("Say it out loud, then. At the meeting.","hurt")],after='apologize')
L('follow','disagree',A,F,[("It came across exactly the way you meant it.","hurt")],after='tell')
L('follow','confront',A,F,[("Grow up.","hurt")],after='confront')
L('close','accept',A,F,[("Good night.","hurt")],after='leave',outcome='open')
F='appointment-offer'
L(N,N,R,F,[("{name} from the governor's office calls while you're between meetings.","calm")])
L('open','greet',A,F,[("It's good news, I promise.","glad")])
