L('follow','press',A,F,[("Think it over. It's not offered twice.","calm")],after='decline')
L('follow','accept',A,F,[("That's understood. It's your voice.","calm")],after='bargain')
L('follow','refuse',A,F,[("I can't promise that on the governor's behalf.","guarded")],after='bargain')
L('reply','agree',Y,F,[("Then yes.","calm")],after='answer')
L('reply','decline',Y,F,[("Then no. Thank the governor for me.","calm")])
F='floor-switch'
L(N,N,R,F,[("The roll call on {bill} is halfway through when {name} comes down the aisle to your desk.","braced")])
L('open','greet',A,F,[("I need you on this one.","braced")])
L('state','request',A,F,[("I'm two short. Change your vote before they call your name.","braced")])
L('reply','agree',Y,F,[("Fine. You'll remember this.","guarded")])
L('reply','refuse',Y,F,[("Then you need somebody who isn't me. My district's against it, and I told them where I'd be.","braced")])
